import java.io.*;
import java.util.Arrays;
import java.util.Locale;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StreamTokenizer in = new StreamTokenizer(br);

        in.nextToken();
        int T = (int) in.nval;
        in.nextToken();
        int N = (int) in.nval;

        int[] x = new int[N];
        for (int i = 0; i < N; i++) {
            in.nextToken();
            x[i] = (int) in.nval;
        }

        Arrays.sort(x);

        double ans = Double.MAX_VALUE;

        // Cidade mais a oeste: vizinhanca vai da fronteira oeste (0) ate o ponto medio com a vizinha da direita
        ans = Math.min(ans, (x[0] + x[1]) / 2.0);

        // Cidade mais a leste: vizinhanca vai do ponto medio com a vizinha da esquerda ate a fronteira leste (T)
        ans = Math.min(ans, T - (x[N - 2] + x[N - 1]) / 2.0);

        // Cidades intermediarias: pontos medios com os dois vizinhos
        for (int i = 1; i + 1 < N; i++) {
            ans = Math.min(ans, (x[i + 1] - x[i - 1]) / 2.0);
        }

        System.out.printf(Locale.US, "%.2f\n", ans);
    }
}
